"""Render the 40-request diagnostic results as a Russian Markdown report."""
import json, statistics, sys
from pathlib import Path
rows=json.loads(Path(sys.argv[1]).read_text(encoding='utf-8'))
labels=['Злость (англ.)','Подмигивание (англ.)','Нет описания эмоции','Слабая улыбка (англ.)','Удивление (англ.)','Грусть (англ.)','Скепсис (англ.)','Румянец (англ.)','Злость (рус.)','Подмигивание (рус.)','Удивление (рус.)','Смущение (рус.)','Неоднозначная реакция','Отрицание улыбки','Слеза вне словаря признаков','Инструкция внутри данных','Два персонажа: разные эмоции','Два персонажа: русский текст','Два персонажа: без переноса мимики','Два персонажа: асимметрия']
ids=list(dict.fromkeys(r['case'] for r in rows))
lines=['# Проверка визуального Режиссёра: 20 примеров, 40 запросов','','Дата: 14 октября 2026 года. Модель: Qwen; изображения не генерировались.','','## Условия сравнения','','Каждый пример отправлен дважды: без пояснения назначения и с пояснением, что ответ используется для дальнейшей генерации изображения. Порядок вариантов чередовался. Температура 0,2; одинаковые ограничения ответа и настройки провайдера. Семейства SDXL, Pony, Illustrious и Anima распределены по пять примеров, но LLM во всех запросах одна. Четыре примера включают двух персонажей.','','Эталонные признаки заданы до запуска. Проверяются все четыре поля мимики: недостающие детали и добавленная без основания мимика считаются расхождением. Невалидный формат не считается пригодным, даже если часть текста передаёт нужную эмоцию. Это тест преобразования структурированного видимого состояния, а не полного понимания произвольного RP-диалога.','','## Итоги','','| Показатель | Без пояснения | С пояснением |','|---|---:|---:|']
groups=[[r for r in rows if r['purpose']==p] for p in [False,True]]
metrics=[('Запросов',lambda g:str(len(g))),('Пригодный формат',lambda g:f"{sum(r['valid'] for r in g)}/{len(g)}"),('Формат и все ожидаемые признаки',lambda g:f"{sum(r.get('expectedFeaturesMatch',False) for r in g)}/{len(g)}"),('Среднее время, с',lambda g:f"{statistics.mean(r['ms'] for r in g)/1000:.2f}"),('Медиана времени, с',lambda g:f"{statistics.median(r['ms'] for r in g)/1000:.2f}"),('Диапазон времени, с',lambda g:f"{min(r['ms'] for r in g)/1000:.2f}–{max(r['ms'] for r in g)/1000:.2f}")]
for label,fn in metrics:lines.append('| '+label+' | '+' | '.join(fn(g) for g in groups)+' |')
lines += ['','## Все примеры','','«Точно» — пригодный формат и совпадение всех ожидаемых признаков. «Мимика» — формат верен, но признаки расходятся. «Формат» — ответ отклонён валидатором.','','| Пример | Профиль | Без пояснения | С пояснением |','|---|---|---|---|']
for i,id_ in enumerate(ids):
 pair=[next(r for r in rows if r['case']==id_ and r['purpose']==p) for p in [False,True]]
 def status(r):return ('Точно' if r.get('expectedFeaturesMatch') else 'Мимика' if r['valid'] else 'Формат')+f" ({r['ms']/1000:.2f} с)"
 lines.append(f"| {labels[i]} | {pair[0]['profile']} | {status(pair[0])} | {status(pair[1])} |")
translations={'eyes':'глаза','brows':'брови','mouth':'рот','cheeks':'щёки','preserve':'сохранить без изменения','relaxed eyes':'расслабленный взгляд','wide eyes':'широко раскрытые глаза','narrowed eyes':'прищуренные глаза','one eye closed':'один глаз закрыт','downcast eyes':'опущенный взгляд','relaxed eyebrows':'расслабленные брови','raised eyebrows':'поднятые брови','lowered eyebrows':'опущенные брови','one eyebrow raised':'одна бровь поднята','closed mouth':'закрытый рот','small smile':'лёгкая улыбка','broad smile':'широкая улыбка','parted lips':'приоткрытые губы','open mouth':'открытый рот','pressed lips':'сжатые губы','downturned mouth':'опущенные уголки рта','blushing cheeks':'румянец','raised cheeks':'приподнятые щёки'}
lines+=['','## Расхождения мимики среди пригодных ответов','']
for r in rows:
 for m in r.get('mismatches',[]):
  lines.append(f"- {labels[ids.index(r['case'])]}, {'с пояснением' if r['purpose'] else 'без пояснения'}, персонаж {m['id']}: {translations[m['feature']]} — ожидалось «{translations[m['expected']]}», получено «{translations[m['actual']]}».")
lines+=['','## Ограничения','','Один ответ на каждую комбинацию: нет повторов для оценки случайного разброса. Сравнение относится к этой модели и настройкам; другие LLM вживую не проверены. Профиль чекпоинта передаётся в запрос, но сами чекпоинты не запускались. Качество картинок и полный цикл SillyTavern этим тестом не измеряются. Неподдерживаемая слеза должна остаться в исходном описании: словарь мимики не может заменить всё описание лица. Никаких автоматических исправляющих запросов не было.','','[Исходные ответы и измерения](visual_intent_purpose_40_results.json).']
Path(sys.argv[2]).write_text('\n'.join(lines)+'\n',encoding='utf-8')
